// with_articles loads each row's `articles` (one_to_many `articles`) with it, in one
// query for all the rows. `configure` narrows them, and can load their edges.
pub fn (q UserQuery) with_articles(configure ...fn (ArticleQuery) ArticleQuery) UserQuery {
	mut next := q
	next.with_articles = true
	next.articles_fns = configure
	return next
}

