// all returns the matching rows, with the requested edges.
pub fn (q UserQuery) all() ![]UserNode {
	rows := load.select_where[models.User](q.graph.client.conn, q.graph.client.prepare_query('users', q.query)!)!
	return q.nodes(rows)
}

// first returns the first matching row, with the requested edges, or a
// `NotFoundError`.
pub fn (q UserQuery) first() !UserNode {
	nodes := q.limit(1).all()!
	if nodes.len == 0 {
		return NotFoundError{
			table: 'users'
		}
	}
	return nodes[0]
}

// nodes loads the requested edges onto `rows`, which the caller already has: one
// query per edge, however many rows there are.
pub fn (q UserQuery) nodes(rows []models.User) ![]UserNode {
	mut nodes := rows.map(UserNode{
		graph: q.graph
		user:  it
	})
	if q.with_articles {
		found := q.load_articles(rows, q.articles_fns)!
		for mut node in nodes {
			node.articles = found[node.user.id.str()] or { [] }
			node.loaded << 'articles'
		}
	}
	for name, fns in q.named_articles {
		found := q.load_articles(rows, fns)!
		for mut node in nodes {
			node.named_articles[name] = found[node.user.id.str()] or { [] }
		}
	}
	if q.with_posts {
		found := q.load_posts(rows, q.posts_fns)!
		for mut node in nodes {
			node.posts = found[node.user.id.str()] or { [] }
			node.loaded << 'posts'
		}
	}
	for name, fns in q.named_posts {
		found := q.load_posts(rows, fns)!
		for mut node in nodes {
			node.named_posts[name] = found[node.user.id.str()] or { [] }
		}
	}
	if q.with_comments {
		found := q.load_comments(rows, q.comments_fns)!
		for mut node in nodes {
			node.comments = found[node.user.id.str()] or { [] }
			node.loaded << 'comments'
		}
	}
	for name, fns in q.named_comments {
		found := q.load_comments(rows, fns)!
		for mut node in nodes {
			node.named_comments[name] = found[node.user.id.str()] or { [] }
		}
	}
	return nodes
}

// load_articles loads the `articles` of `rows`, keyed by each row's key.
fn (q UserQuery) load_articles(rows []models.User, fns []fn (ArticleQuery) ArticleQuery) !map[string][]ArticleNode {
	mut sub := q.graph.articles()
	for configure in fns {
		sub = configure(sub)
	}
	children := sub.nodes(load.select_each[models.Article](q.graph.client.conn, 'user_id',
		rows.map(it.id.str()),
		soft_del: 'deleted_at'
		query:    q.graph.client.prepare_edge_query('articles', sub.query)!
	)!)!
	mut by_parent := map[string][]ArticleNode{}
	for child in children {
		by_parent[child.article.user_id.str()] << child
	}
	return by_parent
}

// articles_or_err returns the `articles`, or a `NotLoadedError` when the query
// didn't load them.
pub fn (n UserNode) articles_or_err() ![]ArticleNode {
	if 'articles' !in n.loaded {
		return NotLoadedError{
			edge: 'users.articles'
		}
	}
	return n.articles
}

// load_posts loads the `posts` of `rows`, keyed by each row's key.
fn (q UserQuery) load_posts(rows []models.User, fns []fn (PostQuery) PostQuery) !map[string][]PostNode {
	mut sub := q.graph.posts()
	for configure in fns {
		sub = configure(sub)
